// Package banner renders the OFA logomark at startup.
//
// The art itself (Art) is generated by scripts/gen-banner at build time
// from ascii.rest's banner module, then frozen as a string constant. The
// runtime cost is one write per call; there is no animation, no font
// parser, and no network access. NO_COLOR (https://no-color.org/) is
// respected: when set, ANSI escapes are stripped so logs and CI captures
// stay plain.
package banner

import (
	"io"
	"os"
	"regexp"
	"strings"
)

// ansiEscape matches every CSI sequence (ESC [ params intermediates final).
// Per ECMA-48: params are 0x30..0x3F, intermediates 0x20..0x2F, final
// 0x40..0x7E. Stripping it is enough to make the art plain text without
// touching the unicode glyphs that draw the letters.
//
// Note: this is a regular string, not a raw string. In a raw string `\x1b`
// is four characters (\, x, 1, b) instead of the byte 0x1b the regex
// engine needs.
var ansiEscape = regexp.MustCompile("\x1b\\[[\\x30-\\x3f]*[\\x20-\\x2f]*[\\x40-\\x7e]")

// Render writes the OFA banner to w. Returns the write error, if any.
//
// When NO_COLOR is set in the environment to a non-empty string, the SGR
// 24-bit color escapes are stripped first; the underlying glyphs are
// unchanged. This matches https://no-color.org/ ("when present and not
// an empty string, regardless of its value, prevents the addition of
// ANSI color") and the convention ascii.rest follows in `play()`.
func Render(w io.Writer) error {
	if v, ok := os.LookupEnv("NO_COLOR"); ok && v != "" {
		_, err := io.WriteString(w, ansiEscape.ReplaceAllString(Art, ""))
		return err
	}
	_, err := io.WriteString(w, Art)
	return err
}

// Plain returns the banner as plain text with no ANSI escapes, regardless
// of NO_COLOR. Convenient for tests and for callers that always want
// uncolored output (e.g., embed in a Markdown doc).
func Plain() string {
	return ansiEscape.ReplaceAllString(Art, "")
}

// Cols and Rows are the rendered banner's dimensions, exported so callers
// can size their layout around it.
const (
	Cols = 35
	Rows = 8
)

// splitLines splits the baked banner on newlines. Used by callers that
// need row-by-row output (e.g., to interleave with picker rows).
func splitLines() []string {
	return strings.Split(Art, "\n")
}